    val n = br.readLine().trim().toInt()

    val stack = ArrayDeque<Int>()

    repeat(n) {
        stack.addLast(1)
        while (stack.size >= 2) {
            val last = stack.removeLast()
            val secondLast = stack.removeLast()
            if (last == secondLast) {
                stack.addLast(last + 1)
            } else {
                stack.addLast(secondLast)
                stack.addLast(last)
                break
            }
        }
    }

    val sb = StringBuilder()
    for ((i, v) in stack.withIndex()) {
        if (i > 0) sb.append(' ')
        sb.append(v)
    }
    println(sb.toString())
}

